+exports.retry = async (fn, { attempts = 3, delayMs = 100 } = {}) => {
+  let last;
+  for (let i = 0; i < attempts; i++) {
+    try {
+      return await fn(i);
+    } catch (err) {
+      last = err;
+      if (i < attempts - 1) await sleep(delayMs);
+    }
+  }
+  throw last;
+};
